document.addEventListener('DOMContentLoaded', function () {
  const smartRecommend = document.querySelector('.product-head-smart-recommend')
  const smartRecommendButton = smartRecommend.querySelector('.smart-recommend-button')

  if (smartRecommend) {
    smartRecommendButton.addEventListener('click', async (e) => {
      // 每次点击都导入模块，但只在首次注册自定义元素
      const module = await import(/* webpackChunkName: "sections-jky-smart-recommend-async" */ '../../../components/sections/jky-smart-recommend/index.js')
      if (!customElements.get('jky-smart-recommend')) {
        customElements.define('jky-smart-recommend', module.default)
      }

      // 每次点击都创建新的模态框实例
      ZModle.getInstance(`
        <jky-smart-recommend
          type="modal"
          compare-id="${e.target.dataset.compareId}"
          coupon-id="${e.target.dataset.couponId}"
        >
          <div slot="loading" class="smart-recommend-loading">
            <svg t="1742798686865" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="10744" width="200" height="200"><path d="M512 170.666667C323.477333 170.666667 170.666667 323.477333 170.666667 512s152.810667 341.333333 341.333333 341.333333 341.333333-152.810667 341.333333-341.333333h85.333334c0 235.648-191.018667 426.666667-426.666667 426.666667S85.333333 747.648 85.333333 512 276.352 85.333333 512 85.333333v85.333334z" p-id="10745" fill="#8a8a8a"></path></svg>
          </div>
        </jky-smart-recommend>
      `, {
        id: 'product-smart-recommend-modal',
        class: "product-smart-recommend-modal",
        destroyOnClose: true, // 关闭时销毁模态框
      })
    })
  }
})
